To exclude the year 2020 from the data, we will add a filter transform to the specification that removes data points where the year of the "date" field is 2020.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://raw.githubusercontent.com/Emilysquires02/Emilysquires02.github.io/main/data_ONS-beir.json",
    "format": {
      "type": "json",
      "property": "years"
    }
  },
  "title": {
    "text": "LFS: ILO redundancy rate: UK ",
    "subtitle": "(per 1,000 employees)",
    "subtitleFontStyle": "italic",
    "subtitleFontSize": 10,
    "anchor": "start",
    "color": "black"
  },
  "width": 180,
  "height": 180,
  "mark": {
    "type": "line",
    "color": "seagreen",
    "strokeWidth": 2,
    "opacity": 1
  },
  "transform": [
    {
      "filter": "year(datum['date']) != 2020"
    }
  ],
  "encoding": {
    "x": {
      "field": "date",
      "type": "temporal",
      "title": null
    },
    "y": {
      "field": "value",
      "type": "quantitative",
      "title": null
    }
  },
  "config": {}
}
```

